            raise InvalidInput('missing atom')
        c = pattern[position]
        if c == 40:
            position += 1
            result = expression()
            if position >= len(pattern) or pattern[position] != 41:
                raise InvalidInput('unclosed group')
            position += 1
            return result
        if c == 46:
            position += 1
            return ('char', ALPHABET)
        if c == 91:
